const publicPages={inicio:['Jeans no atacado em Lajeado | MS Atacado','Jeans no atacado em Lajeado/RS. Compre a partir de 6 peças variadas, com CPF ou CNPJ. Conheça o catálogo, entrega e loja física.'],catalogo:['Catálogo de jeans no atacado | MS Atacado Lajeado','Conheça os modelos de jeans da MS Atacado. Combine modelos e tamanhos a partir de 6 peças e consulte a grade disponível.'],loja:['Loja de jeans no atacado em Lajeado | MS Atacado','Visite a MS Atacado na Rua Fialho de Vargas, 49, sala 101, Centro de Lajeado/RS. Jeans para lojistas e revendedores.'],'como-comprar':['Como comprar jeans no atacado | MS Atacado','Veja como montar seu pedido de jeans na MS: mínimo de 6 peças variadas, compra com CPF ou CNPJ, Pix e cartão em até 12x.'],atendimento:['Contato e WhatsApp | MS Atacado Lajeado','Fale com a MS Atacado pelo WhatsApp (51) 99618-0830. Consulte modelos, grade, pagamento e entrega para sua loja.']};
function publicRoute(){return (decodeURI(location.pathname).replace(/^\/+|\/+$/g,'')||'inicio')+location.search;}
function seoHref(hash){return hash==='#inicio'?'/':/^#(catalogo|loja|como-comprar|atendimento|conta|cadastro|produto\/)/.test(hash)?'/'+hash.slice(1):hash;}
function updateSeo(){const route=(location.hash.slice(1)||publicRoute()).split('?')[0],privatePage=/^(admin|msadm|conta|cadastro)(\/|$)/.test(route)||location.pathname.startsWith('/msadm');let entry=publicPages[route];if(route.startsWith('produto/')&&typeof products!=='undefined'){const p=products.find(p=>p.id===route.slice(8));if(!p){document.querySelector('meta[name=robots]')?.setAttribute('content','noindex,follow');return;}if(p)entry=[p.name+' no atacado | MS Atacado',p.description];}if(entry){for(const [key,value] of [['og:title',entry[0]],['og:description',entry[1]]])document.querySelector('meta[property="'+key+'"]')?.setAttribute('content',value);document.title=entry[0];document.querySelector('meta[name="description"]')?.setAttribute('content',entry[1]);}document.querySelector('meta[name="robots"]')?.setAttribute('content',privatePage?'noindex,nofollow':'index,follow,max-image-preview:large');document.querySelector('link[rel="canonical"]')?.setAttribute('href','https://msatacado-rs.com.br'+(route==='inicio'?'/':'/'+route));document.querySelectorAll('a[href^="#"]').forEach(a=>{const href=seoHref(a.getAttribute('href'));if(href.startsWith('/'))a.setAttribute('href',href);});}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute('download')||location.pathname.startsWith('/msadm'))return;const u=new URL(a.href);if(u.origin!==location.origin||u.hash||!/^\/(catalogo|loja|como-comprar|atendimento|conta|cadastro|produto\/[^/]+)?\/?$/.test(u.pathname))return;e.preventDefault();history.pushState({},'',u.pathname+u.search);route();});
window.addEventListener('popstate',()=>route());
new MutationObserver(updateSeo).observe(document.querySelector('main'),{childList:true,subtree:true});
